tElementById("gxMenu"),toast=document.getElementById("gxToast"),list=null;function say(t){toast.textContent=t;toast.className="gx-toast on";setTimeout(function(){toast.className="gx-toast"},2600)}function load(cb){if(list)return cb();fetch("/picture-messages/img/?idx=1").then(function(r){return r.json()}).then(function(o){list=[];Object.keys(o).map(Number).sort(function(a,b){return a-b}).forEach(function(s){Object.keys(o[s]).map(Number).sort(function(a,b){return a-b}).forEach(function(v){if(String(o[s][v]).indexOf("t")>-1)list.push(s+"."+v+"t")})});cb()}).catch(function(){say("மீண்டும் முயலுங்கள்")})}function show(id){cur=id;img.src="/picture-messages/img/?f="+id;lk.href="/picture-messages/#"+id}function step(d){load(function(){var i=list.indexOf(cur);if(i<0)i=0;show(list[(i+d+list.length)%list.length])})}function pageUrl(){return location.origin+"/picture-messages/share/"+cur+"/"}function blob(){return fetch("/picture-messages/img/?f="+cur+"&s=full").then(function(r){return r.blob()})}document.getElementById("gxPrev").onclick=function(){step(-1)};document.getElementById("gxNext").onclick=function(){step(1)};document.getElementById("gxDl").onclick=function(){blob().then(function(b){var u=URL.createObjectURL(b),a=document.createElement("a");a.href=u;a.download="GodAlone-Quran-"+cur+(b.type==="image/jpeg"?".jpg":".png");document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u)},4000);say("பதிவிறக்கப்படுகிறது…")}).catch(function(){say("மீண்டும் முயலுங்கள்")})};document.getElementById("gxSh").onclick=function(e){e.stopPropagation();menu.hidden=!menu.hidden};document.addEventListener("click",function(){menu.hidden=true});function copy(){var u=pageUrl();if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(u).then(function(){say("இணைப்பு நகலெடுக்கப்பட்டது")},function(){say(u)})}else{var t=document.createElement("textarea");t.value=u;document.body.appendChild(t);t.select();try{document.execCommand("copy");say("இணைப்பு நகலெடுக்கப்பட்டது")}catch(x){say(u)}t.remove()}}menu.addEventListener("click",function(e){var a=e.target.closest("a");if(!a)return;e.preventDefault();var s=a.getAttribute("data-s"),u=encodeURIComponent(pageUrl()),t=encodeURIComponent("குர்ஆன் வசனம் - KadavulMattum.org");if(s==="wa")window.open("https://wa.me/?text="+t+"%20"+u,"_blank","noopener");else if(s==="tg")window.open("https://t.me/share/url?url="+u+"&text="+t,"_blank","noopener");else if(s==="fb")window.open("https://www.facebook.com/sharer/sharer.php?u="+u,"_blank","noopener");else if(s==="cp")copy();else if(s==="ig"){if(navigator.canShare&&navigator.share){blob().then(function(b){var f=new File([b],"GodAlone-"+cur+(b.type==="image/jpeg"?".jpg":".png"),{type:b.type});if(navigator.canShare({files:[f]}))return navigator.share({files:[f],text:"KadavulMattum.org"});copy();say("இணைப்பு நகலெடுக்கப்பட்டது. Instagram-இல் ஒட்டுங்கள்.")}).catch(function(){})}else{copy();say("இணைப்பு நகலெடுக்கப்பட்டது. Instagram-இல் ஒட்டுங்கள்.")}}menu.hidden=true})})();</script>


<style>
